// Chapter 4 — Communications and Documentation.
// The handover structure is taught as a principle with the common formats
// named, rather than mandating one: structured handover reduces information
// loss, and the evidence that any particular tool beats another is weak. A
// service that has chosen SBAR, MIST or IMIST-AMBO should pin that choice in
// the local overlay; the block teaches what any of them has to carry.
const STD='NHTSA National EMS Education Standards (2021) — Preparatory: Communications and Documentation.';
const HAND='Dawson S, King L, Grantham H. Improving the hospital clinical handover between paramedics and emergency department staff. Emerg Med Australas 2013;25:393–405.';
const INT='Flores G. The impact of medical interpreter services on the quality of health care: a systematic review. Med Care Res Rev 2005;62:255–99.';
const ADA='Americans with Disabilities Act, 28 CFR 35.160 — effective communication and auxiliary aids.';
const NEMSIS='NEMSIS version 3 data dictionary — the national EMS dataset.';
const NIMS='FEMA National Incident Management System — common terminology and plain language.';

const opt=(id,text,correct,rationale)=>({id,text,correct,rationale});
const base=(o)=>({stimulus:{kind:'none',ref:null},bloom:'apply',nremt_domain:'ems_operations',
  cj_step:null,difficulty_seed:0.5,high_stakes:false,reviewed_by:null,
  review_status:'unreviewed',version:'1.0.0',...o});

export const objectives=[
 {id:'obj-4.1.a',chapter:4,tier:'core',text:'Apply therapeutic communication techniques that actually improve the history you get',
  enables:'Get the information the rest of your assessment depends on, from someone who has no reason to trust you yet'},
 {id:'obj-4.2.a',chapter:4,tier:'core',text:'Adapt communication for hearing loss, language, cognitive impairment, age and culture',
  enables:'Keep assessing a patient who cannot answer you the usual way'},
 {id:'obj-4.3.a',chapter:4,tier:'core',text:'Use radio and dispatch communication correctly, including plain language and read-back',
  enables:'Be understood the first time, on a channel other people need'},
 {id:'obj-4.4.a',chapter:4,tier:'context',text:'Communicate with crew, family and other agencies under pressure',
  enables:'Say the hard thing to a colleague on scene, in a way that gets heard'},
 {id:'obj-4.5.a',chapter:4,tier:'core',text:'Give a structured verbal handover that carries everything the receiving team needs',
  enables:'Hand over in ninety seconds without losing the thing that mattered'},
 {id:'obj-4.6.a',chapter:4,tier:'core',text:'Explain what the patient care report is for and who reads it afterwards',
  enables:'Write for the four different readers your report will actually have'},
 {id:'obj-4.7.a',chapter:4,tier:'core',text:'Write a narrative that is objective, specific and defensible',
  enables:'Produce a record that still means something two years later, to someone who was not there'},
 {id:'obj-4.8.a',chapter:4,tier:'core',text:'Correct errors, make late entries, and recognise falsification',
  enables:'Fix a charting mistake in the way that protects you rather than the way that ends a career'},
 {id:'obj-4.9.a',chapter:4,tier:'context',text:'Document refusals, no-transports, restraint and multiple-casualty incidents',
  enables:'Keep a usable record in the situations where the record is most likely to be read'},
 {id:'obj-4.INT.a',chapter:4,tier:'core',text:'Integrate assessment communication, handover and documentation across one call',
  enables:'Carry one patient’s story from a doorway to a chart without dropping any of it'}
];

